import{_ as t,l as r,o,c as l,v as e,p as E,x as i,d as s,i as A,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"Nikon 对 ASML","description":"","frontmatter":{"title":"Nikon 对 ASML","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/nikon-vs-asml.md","filePath":"litho/nikon-vs-asml.md","lastUpdated":1789023840000}'),d={name:"litho/nikon-vs-asml.md"};function h(V,a,B,S,c,m){const n=r("Mermaid");return o(),l("div",null,[a[1]||(a[1]=e('<h1 id="nikon-对-asml" tabindex="-1">Nikon 对 ASML <a class="header-anchor" href="#nikon-对-asml" aria-label="Permalink to &quot;Nikon 对 ASML&quot;">​</a></h1><div class="epigraph"><p>浸没时代的领先扫描机不是物理上只可能有一家；公开史上，双工件台、浸没与后来的 EUV 集成，把可买到的先进机台收敛到 ASML 这条链上。</p><footer>—— 对照浸没光刻竞争的公开 Chronology；EUV 商业供应见 ASML / 出口管制公开事实</footer></div><p><a href="/litho/euv-export-control">上一课</a>把量产 EUV 写成一条商业供应链，并用许可制度解释它进不了部分市场。缺口是：这条集中从哪来。本课钉 Nikon 对 ASML 的公开竞争史——浸没阶段仍有对手，EUV 阶段公开可交货的是 ASML。不编市场份额百分数，不写未公开订单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>出口管制课的前提是「EUV 扫描仪商业上只有 ASML」。读者会问：193 浸没不是还有 Nikon 吗？有。Canon 也曾做扫描机，后来退出领先逻辑这条赛道。公开史是：ArF 干式与浸没阶段，ASML 与 Nikon 都卖过先进扫描机；ASML 的 TWINSCAN 双工件台（一台测量、一台曝光）成为高吞吐架构的公开标杆；浸没 NA 走到 1.35 一类量产点后，客户在逻辑领先节点上越来越集中到 ASML 平台。EUV 则从一开始就是 ASML + 蔡司投影 + Cymer 光源的垂直整合，Nikon 没有对等的量产 EUV 产品线进入同一市场。</p><p>本课要的是这条<strong>公开叙事</strong>，不是把管制原因写成「因为 Nikon 输了」。管制管的是已存在的 EUV 供应链；竞争史解释为何浸没高端也被同一家深度占据。</p><h3 id="不要把「谁赢了」写成物理定律" tabindex="-1">不要把「谁赢了」写成物理定律 <a class="header-anchor" href="#不要把「谁赢了」写成物理定律" aria-label="Permalink to &quot;不要把「谁赢了」写成物理定律&quot;">​</a></h3><p>双工件台提高可用性与套刻闭环效率，不是光学 NA 公式。浸没液、镜头、工件台、光源、软件一起才是机台。Nikon 继续提供浸没机给特定市场与节点，公开事实允许「仍有第二家浸没供应商」，同时允许「领先逻辑 EUV 产线以 ASML 为商业来源」。两句都要写，才不会变成宣传稿。</p><p><span class="marginnote">禁止编造全球份额、台数或营收比。课标只使用架构事实、产品代际的公开存在、以及 EUV 商业供应关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读史按层：干式 ArF 多家 → 浸没引入后 ASML/Nikon 公开竞赛 → 双工件台与浸没高 NA 的系统集成差异显现于客户选择 → EUV 研发投入与蔡司/Cymer 绑定使量产 EUV 只有一条交货链。中国节点课要写国产浸没与多重曝光，前提正是：没有 EUV 时，浸没机（含 Nikon 与其它）仍是物理工具；有 EUV 的那条成本曲线被管制钉住。</p><p>写供应链时分开：浸没镜头与 EUV 多层投影不是同一货架。蔡司 EUV POB 的公开绑定是 EUV 集中的技术原因之一，不要把浸没镜头竞争直接外推。</p><h3 id="与出口管制的接口" tabindex="-1">与出口管制的接口 <a class="header-anchor" href="#与出口管制的接口" aria-label="Permalink to &quot;与出口管制的接口&quot;">​</a></h3><p>管制对象是 ASML 的 EUV（以及后来的高端浸没许可实践），不是「禁止 Nikon 存在」。先进逻辑若只被禁止买 EUV，仍可能买或用已安装的浸没做多重图形，见 <a href="/litho/china-duv-multipattern">国产 DUV 多重曝光</a>。竞争史解释工具菜单有多窄，不管制条款本身。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>客户锁定来自工艺包与机台生态：OPC、套刻模型、胶与照明配方在某一代扫描机上标定，换供应商等于重做 DTCO。双工件台把测量与曝光并行，吞吐与 on-product overlay 的工程闭环更紧，这是公开架构优势，不是一句「光学更好」。EUV 再把光源、真空台、多层镜加成更高的进入壁垒。于是浸没阶段的领先地位与 EUV 研发投入互相放大。</p><p>Nikon 的公开位置：浸没扫描机供应商之一，EUV 量产交货未进入与 ASML 对等的逻辑产线叙事。写「对」不是写「消灭」。</p><p><span class="marginnote">Canon 退出领先扫描机赛道是公开史的一部分，但本课标题是 Nikon 对 ASML，不把第三家的内部决策写进未公开原因。</span></p>',18)),(o(),E(p,null,{default:i(()=>[A(n,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRY%5B%22%E5%B9%B2%E5%BC%8F%20ArF%20%E5%A4%9A%E5%AE%B6%22%5D%20--%3E%20IMM%5B%22%E6%B5%B8%E6%B2%A1%3A%20ASML%20%E4%B8%8E%20Nikon%22%5D%0A%20%20IMM%20--%3E%20DUAL%5B%22%E5%8F%8C%E5%B7%A5%E4%BB%B6%E5%8F%B0%E7%AD%89%E7%B3%BB%E7%BB%9F%E9%9B%86%E6%88%90%22%5D%0A%20%20IMM%20--%3E%20EUV%5B%22%E9%87%8F%E4%BA%A7%20EUV%3A%20ASML%20%E9%93%BE%22%5D%0A%20%20EUV%20--%3E%20CTRL%5B%22%E5%87%BA%E5%8F%A3%E8%AE%B8%E5%8F%AF%E9%92%89%E4%BD%8F%20EUV%20%E6%89%A9%E6%95%A3%22%5D%0A%20%20IMM%20--%3E%20MULTI%5B%22%E6%97%A0%20EUV%20%E5%88%99%E6%B5%B8%E6%B2%A1%E5%A4%9A%E9%87%8D%E5%9B%BE%E5%BD%A2%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写 ECCN 条款，也不评价未公开的客户谈判。禁止份额数字、禁止内部路线图。浸没镜头、光源和工件台仍可分开讨论；EUV 把三者绑进同一交货链，这才是「对 ASML」在本课的终点。后课国产浸没与多重曝光默认：工具菜单里仍有浸没机，没有对等的量产 EUV。</p><p>引用公开产品史、ASML TWINSCAN / EUV 公开叙述、Nikon 作为浸没供应商的公开存在。</p><p><span class="marginnote">「只有 ASML 能做 EUV」指商业量产扫描仪供应链，不是声称其它实验室光源物理上不可能发光。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>浸没阶段 ASML 与 Nikon 都是公开竞争对手；领先逻辑后来集中到 ASML 平台。</li><li>双工件台等系统集成是公开架构差异，不是 NA 公式注定。</li><li>量产 EUV 商业链是 ASML + 蔡司 + Cymer；Nikon 未进入对等交货叙事。</li><li>不管制史实、不编份额；管制课管的是这条已存在的链。</li><li>客户锁定来自工艺包与机台生态，换供应商等于重做 DTCO。</li><li>出处：浸没竞争公开史；ASML / 管制公开事实。</li></ul>',6))])}const U=t(d,[["render",h]]);export{k as __pageData,U as default};
